plugins {
    id("org.jetbrains.kotlin.jvm")
}

kotlin {
    jvmToolchain(17)
    explicitApiWarning()
}

dependencies {
    testImplementation(kotlin("test-junit"))
    testImplementation("junit:junit:4.13.2")
}

tasks.test {
    useJUnit()
    // Shared wire-format ground truth, generated by protocol/tools/gen_vectors.py.
    systemProperty("vectors.dir", rootProject.file("../protocol/vectors").absolutePath)
    systemProperty("firmware.vectors.dir", rootProject.file("../protocol/vectors").absolutePath)
    testLogging {
        events("passed", "failed", "skipped")
        showStandardStreams = false
    }
    // STOP/late-response matrix size is part of the deliverable; fail loudly if the
    // test class stops running (guards against silently losing coverage).
    filter {
        isFailOnNoMatchingTests = true
    }
}
